import "array"

array.from(rows: [
  {
    metric: "CampusStatus",
    value:
      if 35 == 35 and 35 == 35 and 4 == 4 and 1 == 1 and 25 == 25 then 0
      else if 4 < 4 or 1 < 1 then 2
      else 1
  }
])

import "array"
import "join"

expected_core =
    array.from(
        rows: [
            {SwitchIP: "192.168.1.1"},
            {SwitchIP: "192.168.2.70"},
            {SwitchIP: "192.168.2.71"},
            {SwitchIP: "192.168.2.72"},
            {SwitchIP: "192.168.2.73"}
        ]
    )
    |> group(columns: ["SwitchIP"])

recent_core =
    from(bucket: "telegraf")
        |> range(start: -15m)
        |> filter(fn: (r) => r._measurement == "snmp" and r._field == "sysUpTime")
        |> group(columns: ["source"])
        |> last()
        |> map(fn: (r) => ({
            SwitchIP: string(v: r.source),
            OnlineFlag: 1
        }))
        |> group(columns: ["SwitchIP"])

join.left(
    left: expected_core,
    right: recent_core,
    on: (l, r) => l.SwitchIP == r.SwitchIP,
    as: (l, r) => ({
        SwitchIP: l.SwitchIP,
        MissingCount: if exists r.OnlineFlag then 0 else 1
    })
)
    |> group(columns: [])
    |> reduce(
        identity: {MissingCount: 0},
        fn: (r, accumulator) => ({
            MissingCount: accumulator.MissingCount + r.MissingCount
        })
    )

from(bucket: "telegraf")
  |> range(start: -30m)
  |> filter(fn: (r) =>
    r._measurement == "snmp" and
    r._field == "sysUpTime" and
    (exists r.sysDescr or exists r.sysName)
  )

  // ONE ROW PER PHYSICAL DEVICE
  |> group(columns: ["source"])
  |> last()

  |> map(fn: (r) => ({
    sysName: if exists r.sysName then string(v: r.sysName) else "",
    sysDescr: if exists r.sysDescr then string(v: r.sysDescr) else "",
    uptime_days: float(v: r._value) / 8640000.0
  }))

  // CLASSIFICATION (FortiGate by sysName, others by sysDescr)
  |> map(fn: (r) => ({
    Group:
      if r.sysName =~ /FortiGate1-Sccc/ then "FortiGate Firewall"
      else if r.sysDescr =~ /Cisco.*(Nexus|NX-OS)/ then "Cisco Nexus"
      else if r.sysDescr =~ /Aruba/ then "Access Switch"
      else "Firewall",
    severity:
      if r.uptime_days < 1.0 then 2
      else if r.uptime_days < 7.0 then 1
      else 0,
    uptime_days: r.uptime_days
  }))

  |> group(columns: ["Group"])
  |> reduce(
    identity: { count: 0, max_sev: 0, sum_uptime: 0.0 },
    fn: (r, accumulator) => ({
      count: accumulator.count + 1,
      max_sev:
        if r.severity > accumulator.max_sev then r.severity else accumulator.max_sev,
      sum_uptime: accumulator.sum_uptime + r.uptime_days
    })
  )

  |> group(columns: [])
  |> map(fn: (r) => ({
    DeviceType: r.Group,
    Count: r.count,
    Status:
      if r.max_sev == 2 then "Red"
      else if r.max_sev == 1 then "Yellow"
      else "Green",
    AvgUptimeDays:
      if r.count > 0 then r.sum_uptime / float(v: r.count) else 0.0
  }))

  |> keep(columns: ["DeviceType", "Count", "Status", "AvgUptimeDays"])
  |> sort(columns: ["DeviceType"])

